import { CopyIcon, LinkedInLogoIcon, Share1Icon } from "@radix-ui/react-icons";
import { Box, Flex, IconButton, Link, Text } from "../../atoms";
import { useEffect, useState } from "react";
import { useOutsideClick } from "../../utils/hooks/useOutsideClick";
import { DiscordIcon, XIcon, LinkedinIcon, CopyLinkIcon } from "../../icons";
import { CSS } from "../../../stitches.config";

type ShareIconButtonProps = {
  onClick: () => void;
};

const ShareIconButton = (props: ShareIconButtonProps) => {
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    props.onClick();
  };
  return (
    <IconButton
      onClick={handleClick}
      css={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        p: 0,
        backgroundColor: "$obolGreen",
        width: "$2xl",
        height: "$2xl",
        borderRadius: "50%",
        color: "$bg01",
        "&:hover": {
          backgroundColor: "$obolGreen",
        },
      }}
    >
      <Share1Icon width="24px" height="24px" />
    </IconButton>
  );
};

type CopyTextProps = {
  css?: CSS;
};

const CopyText = (props: CopyTextProps) => {
  return (
    <Box
      css={{
        position: "absolute",
        right: "100%",
        marginRight: "10px",
        width: "$max",
        backgroundColor: "$bg05",
        py: "$xxs",
        px: "$xs",
        borderRadius: "30px",
        ...props.css,
      }}
    >
      <Text>Link copied!</Text>
    </Box>
  );
};

const flexCss = {
  position: "absolute",
  flexDirection: "column",
  width: "$xl",
  height: "152px",
  bottom: "50px",
  mx: "auto",
  left: 0,
  right: 0,
  alignItems: "center",
  justifyContent: "space-between",
};

const linkCss = {
  cursor: "pointer",
  color: "$bg05",
  "& svg": {
    "& path": {
      fill: "$bg05",
      stroke: "$bg05",
    },
  },
  "&:hover": {
    color: "$obolGreen",
    "& svg": {
      "& path": {
        fill: "$obolGreen",
        stroke: "$obolGreen",
      },
    },
  },
};

const useCopyText = () => {
  const [showCopyText, setShowCopyText] = useState(false);
  useEffect(() => {
    if (showCopyText) {
      const timeout = setTimeout(() => {
        setShowCopyText(false);
      }, 2000);

      return () => clearTimeout(timeout);
    }
  }, [showCopyText]);
  return { showCopyText, setShowCopyText };
};

const getTwitterHref = (url: string) => {
  let twitterUrl = url;
  twitterUrl.replace(/:/g, "%3A");
  twitterUrl.replace(/\//g, "%2F");
  return `https://twitter.com/intent/post?text=Checkout%20my%20Operator%20profile%20on%20Obol's%20DV%20Launchpad!%20&url=${twitterUrl}`;
};

const getLinkedinHref = (url: string) => {
  let linkedinUrl = url;
  linkedinUrl.replace(/:/g, "%3A");
  return `https://www.linkedin.com/shareArticle?mini=true&url=${linkedinUrl}`;
};

export type ShareButtonProps = {
  url: string;
};

export const ShareButton = (props: ShareButtonProps) => {
  const [show, setShow] = useState(false);
  const { showCopyText, setShowCopyText } = useCopyText();
  const ref = useOutsideClick(() => setShow(false));

  const twitterHref = getTwitterHref(props.url);
  const linkedinHref = getLinkedinHref(props.url);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(props.url);
      setShowCopyText(true);
    } catch (error) {
      console.error("Unable to copy to clipboard:", error);
    }
  };

  return (
    <Flex
      ref={ref}
      css={{
        position: "relative",
        width: "$2xl",
        height: "$2xl",
      }}
    >
      <ShareIconButton onClick={() => setShow(!show)} />
      <Flex css={{ ...flexCss, display: show ? "flex" : "none" }}>
        <Box css={{ position: "relative", ...linkCss }} onClick={handleCopy}>
          <CopyText css={{ display: showCopyText ? "flex" : "none" }} />
          <CopyLinkIcon />
        </Box>
        <Link target="_blank" css={linkCss} href={twitterHref}>
          <XIcon />
        </Link>
        <Link
          target="_blank"
          css={linkCss}
          href="https://discord.gg/obol"
        >
          <DiscordIcon />
        </Link>
        <Link target="_blank" css={linkCss} href={linkedinHref}>
          <LinkedinIcon />
        </Link>
      </Flex>
    </Flex>
  );
};
